/**
 * Draft-only mode for auto-generated posts (D23).
 *
 * Auto-generated posts are written as `draft` (or `ready` when a channel sets
 * `requireApproval = false`). The publishing scheduler only selects `scheduled`
 * rows, so generated content cannot publish without a human promoting it.
 */

/** The status every auto-generated post is created with. */
export const AUTO_GENERATED_POST_STATUS = "draft" as const;

/**
 * The status an auto-generated post gets when the operator has explicitly asked
 * for it to skip manual review (`requireApproval = false`). Queued and visible
 * to the operator, but not publishable by the scheduler.
 */
export const PRE_APPROVED_AUTO_POST_STATUS = "ready" as const;

/**
 * Status for an auto-generated post given the operator's approval preference.
 * Any non-`false` value (including NULL/undefined) defaults to `draft`.
 */
export function autoGeneratedStatusFor(requireApproval: boolean | null | undefined): string {
  return requireApproval === false ? PRE_APPROVED_AUTO_POST_STATUS : AUTO_GENERATED_POST_STATUS;
}

/**
 * Statuses that occupy a publishing slot in calendar autofill so repeated runs
 * do not generate duplicate drafts for the same slot.
 */
export const SLOT_OCCUPYING_STATUSES = ["draft", "ready", "scheduled"] as const;

/**
 * Statuses that the publishing scheduler is allowed to pick up.
 * Deliberately excludes `draft` and `ready`.
 */
export const PUBLISHABLE_STATUSES = ["scheduled"] as const;

export function occupiesSlot(status: string | null | undefined): boolean {
  return !!status && (SLOT_OCCUPYING_STATUSES as readonly string[]).includes(status);
}

export function isPublishable(status: string | null | undefined): boolean {
  return !!status && (PUBLISHABLE_STATUSES as readonly string[]).includes(status);
}
